from PIL import Image, ImageFilter
import numpy as np
im=Image.open('radiograph.jpg').convert('L')
a=np.array(im).astype(float)
bg=np.array(im.filter(ImageFilter.GaussianBlur(45))).astype(float)
d=np.clip(bg-a,0,60)
h,w=d.shape
# simple non-max suppression grid
cands=[]
for yy in range(30,h-30,15):
  for xx in range(30,w-30,15):
    patch=d[yy-25:yy+25,xx-25:xx+25]
    if patch.max()>20 and d[yy,xx]>=patch.max()-2:
      cands.append((d[yy,xx],xx,yy))
cands.sort(reverse=True)
picked=[]
for v,x,y in cands:
  if all((x-px)**2+(y-py)**2>80**2 for _,px,py in picked):
    picked.append((v,x,y))
for v,x,y in picked[:30]: print(round(v,1),x,y)
print(len(picked))
"", "description": "Non-max supressed dark blob peaks"}
